__NUXT_JSONP__("/svet/stat/alzirsko/flora", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{tabsLoad:{tabWhatToSee:b,tabPrice:b,tabPeople:b,tabTrip:b,tabContact:b,tabHotel:b,tabNeighboring:7,tabVideos:f,tabArticles:f,tabWallSockets:i,tabChains:1,tabFauna:f,tabFlora:f,tabFoods:e,tabBrands:f},place:[{tld:".dz",name:"Alžírsko",area:2381741,population:43000000,slug:j,id_continent:e,information_chatgpt:"\u003Cp\u003EAlžírsko je největší zemí v Africe a desátým největším státem na světě. Nachází se na severu Afriky a hraničí s Tuniskem, Libyí, Nigerem, Mali, Mauritánií, Západní Saharou, Marokem a Středozemním mořem.\u003C\u002Fp\u003E\n\u003Cp\u003EZemě má bohatou historii, která sahá až do antiky. Alžírsko bylo dlouho součástí Osmanské říše a později francouzskou kolonií. V roce 1962 získalo nezávislost a stalo se republikou.\u003C\u002Fp\u003E\n\u003Cp\u003EAlžírsko nabízí návštěvníkům mnoho krásných a zajímavých míst, jako jsou například pouště Sahara a Tassili n'Ajjer, které jsou zařazeny na seznamu UNESCO. Kromě toho můžete navštívit také mnoho historických památek, jako jsou starobylá města, pevnosti a mešity.\u003C\u002Fp\u003E\n\u003Cp\u003EMěstem, které byste neměli vynechat, je hlavní město Alžír. Toto město nabízí návštěvníkům mnoho zajímavých památek, jako je například kasbah, bazary, mešity a muzea. Také si můžete prohlédnout krásnou pláž a přístav, kde se můžete projet na lodi a podívat se na město z vodního pohledu.\u003C\u002Fp\u003E\n\u003Cp\u003EKromě toho Alžírsko nabízí i kulturní zážitky, jako jsou tradiční tance, hudba a gastronomie. Alžírská kuchyně je ovlivněna arabskými, berberskými a francouzskými tradicemi a nabízí mnoho zajímavých chutí.\u003C\u002Fp\u003E\n\u003Cp\u003EAlžírsko má mnoho zajímavých míst, která stojí za návštěvu a nabízí návštěvníkům možnost poznat bohatou historii a kulturu této země. Pokud máte rádi dobrodružství a exotická místa, Alžírsko je skvělou volbou pro vaši další dovolenou.\u003C\u002Fp\u003E",currency_code:"DZD",currency_name:"alžírský dinár",money_prices:[{name:"Taxi (cena za km)",value:35,date_update:a},{name:"Hlavní jídlo",value:800,date_update:a},{name:"Chleba",value:k,date_update:a},{name:"Mléko",value:50,date_update:a},{name:"Voda (500ml)",value:k,date_update:a},{name:"Espresso",value:l,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:l,date_update:a},{name:"Pivo",value:200,date_update:a},{name:"Krabička cigaret",value:400,date_update:a},{name:"Bic Mac",value:c,date_update:"Není k dispozici v Alžírsku"},{name:"Coca Cola (500ml)",value:40,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:d},{name:"Policie",value:"17",date_update:d},{name:"Hasiči",value:"14",date_update:d},{name:"Zdravotnická záchranná služba",value:"19",date_update:d}],phone_prefix:"+213",coordinates:[{latitude:"28.0339",longitude:"1.6596"}],people_religion:[{name:"Islám",value:"99.0%"},{name:"Judaismus",value:"0.1%"},{name:"Jiné",value:"0.9%"}],people_nationality:[{name:"Arabové",value:"80.00%"},{name:"Berbeři",value:"20.00%"}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Alžírska je potřeba mít platný cestovní pas, občanský průkaz nestačí.",date_update:g},{name:"Cestovní pas",value:"Pro vstup do Alžírska je nutné mít platný cestovní pas s minimální platností 6 měsíců od data vstupu do země.",date_update:g},{name:"Vízum",value:"Pro vstup do Alžírska je většinou potřeba vízum, které je nutné si předem zařídit na ambasádě. Výjimkou jsou některé země, s nimiž Alžírsko má podepsané smlouvy o zjednodušení vízového režimu. Pro občany ČR je nutné vízum získat předem.",date_update:g},{name:"Očkování",value:"Pro vstup do Alžírska není povinné očkování, avšak doporučuje se očkování proti žluté zimnici. Dále je vhodné být očkován proti hepatitidě A a B a být chráněn proti malárii.",date_update:g},{name:"Cestovní pojištění",value:"Cestovní pojištění není vyžadováno, ale doporučuje se mít sjednané zdravotní pojištění s plnou platností v Alžírsku.",date_update:d},{name:"Bezpečnostní situace",value:"Alžírsko má vysokou úroveň bezpečnosti, ale stále se vyskytují teroristické hrozby a kriminalita. Cestovatelé by měli být obezřetní a dodržovat bezpečnostní pokyny.",date_update:d},{name:"Další informace",value:"V Alžírsku je třeba respektovat místní zvyklosti a tradice, zejména v náboženských a konzervativních oblastech. Také se doporučuje být respektující k místním zvyklostem a kulturám. Dále je důležité dodržovat předpisy a zákony, zejména v oblasti fotografování, kde je třeba mít povolení od místních úřadů. Stejně tak platí zákaz fotografování vůbec v blízkosti vojenských objektů.",date_update:d}],type_place:m,id_image_cover:h,id_image_hero:h,id_city_main:588,affiliate:[{name:"booking",value:b}],mpz:"DZ",alerts:[],zoom:[{google:4,booking:e}],ids_neighboring_countries:[{id:136},{id:145},{id:137},{id:151},{id:162},{id:223},{id:66}],organization:[],apps:[],links:[],information_author:[],seo_tags:[],language_phrases:[],wall_sockets:c,id:62,facts_place:c,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00",name_original:c}],imagePlace:[{id:h,name:j,source:"\u002Fworld\u002Fstates\u002F",type:m,author:"pixabay.com",created_at:"2023-05-02T18:46:02.666888+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:e,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:e,id_image_hero:e,zoom:[{google:i,booking:3}],information_author:c,seo_tags:c,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:c}]}],fetch:{},mutations:[]}}("Duben 2021",true,null,"05-2023",5,0,"09-2021",217,2,"alzirsko",30,60,"state")));